record.field:
{
    "type": "object",
    "properties": {
        "action_report_id": {
            "type": "integer",
            "minimum": 1,
            "description": "action_report_id returned by accounting_report_list. This identifies the report referenced by the client action; do not substitute report_config.options.report_id or a variant/section ID."
        },
        "option_overrides": {
            "type": "object",
            "description": "Optional intentional changes keyed by option name. Apart from date, use only names in available_option_overrides. These are native Odoo option names. Omit defaults; false and empty lists are intentional values.",
            "properties": {
                "date": {
                    "type": "object",
                    "description": "Named periods and single-date reports use date_to only; a custom range also needs date_from.",
                    "properties": {
                        "period_type": {"type": "string", "enum": ["today", "month", "quarter", "year", "custom"]},
                        "date_from": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
                        "date_to": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
                    },
                    "required": ["period_type", "date_to"]
                },
                "comparison": {
                    "type": "object",
                    "description": "Use only fields belonging to the selected comparison form.",
                    "properties": {
                        "filter": {"type": "string", "enum": ["no_comparison", "previous_period", "same_last_year", "custom"]},
                        "number_period": {"type": "integer", "minimum": 1},
                        "date_from": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
                        "date_to": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
                    },
                    "required": ["filter"]
                },
                "journals": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {"id": {"type": "integer"}, "selected": {"type": "boolean"}},
                        "required": ["id", "selected"]
                    }
                },
                "analytic_accounts_groupby": {"type": "array", "items": {"type": "integer"}},
                "partner_ids": {"type": "array", "items": {"type": "integer"}},
                "partner_categories": {"type": "array", "items": {"type": "integer"}},
                "account_type": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "id": {"type": "string", "enum": ["trade_receivable", "non_trade_receivable", "trade_payable", "non_trade_payable"]},
                            "selected": {"type": "boolean"}
                        },
                        "required": ["id", "selected"]
                    }
                },
                "all_entries": {"type": "boolean"},
                "unreconciled": {"type": "boolean"},
                "hierarchy": {"type": "boolean"},
                "tax_unit": {"type": "integer", "minimum": 1},
                "selected_horizontal_group_id": {"type": "integer", "minimum": 1}
            },
            "required": []
        },
        "offset": {"type": "integer", "minimum": 0},
        "limit": {"type": "integer", "minimum": 1, "description": "Page size from 1 to 200; defaults to 60."}
    },
    "required": ["action_report_id"]
}

{
    "type": "object",
    "properties": {
        "report_config_ref": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{24}$",
            "description": "Required exact configuration returned by the describe or select result that exposed this choice. It binds the current user, source action, top-level report entry, selected companies, native options, and selected identity. A stale or mismatched configuration fails closed."
        },
        "choice": {
            "type": "object",
            "description": "Use kind variant with an ID from report_config.options.available_variants, or kind section with an ID from report_config.options.sections in the supplied configuration.",
            "properties": {
                "kind": {"type": "string", "enum": ["variant", "section"]},
                "id": {"type": "integer", "minimum": 1}
            },
            "required": ["kind", "id"]
        },
        "option_overrides": {
            "type": "object",
            "description": "Optional intentional changes keyed by option name. Apart from date, use only names in available_option_overrides. These are native Odoo option names. Omit defaults; false and empty lists are intentional values.",
            "properties": {
                "date": {
                    "type": "object",
                    "description": "Named periods and single-date reports use date_to only; a custom range also needs date_from.",
                    "properties": {
                        "period_type": {"type": "string", "enum": ["today", "month", "quarter", "year", "custom"]},
                        "date_from": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
                        "date_to": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
                    },
                    "required": ["period_type", "date_to"]
                },
                "comparison": {
                    "type": "object",
                    "description": "Use only fields belonging to the selected comparison form.",
                    "properties": {
                        "filter": {"type": "string", "enum": ["no_comparison", "previous_period", "same_last_year", "custom"]},
                        "number_period": {"type": "integer", "minimum": 1},
                        "date_from": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
                        "date_to": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
                    },
                    "required": ["filter"]
                },
                "journals": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {"id": {"type": "integer"}, "selected": {"type": "boolean"}},
                        "required": ["id", "selected"]
                    }
                },
                "analytic_accounts_groupby": {"type": "array", "items": {"type": "integer"}},
                "partner_ids": {"type": "array", "items": {"type": "integer"}},
                "partner_categories": {"type": "array", "items": {"type": "integer"}},
                "account_type": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "id": {"type": "string", "enum": ["trade_receivable", "non_trade_receivable", "trade_payable", "non_trade_payable"]},
                            "selected": {"type": "boolean"}
                        },
                        "required": ["id", "selected"]
                    }
                },
                "all_entries": {"type": "boolean"},
                "unreconciled": {"type": "boolean"},
                "hierarchy": {"type": "boolean"},
                "tax_unit": {"type": "integer", "minimum": 1},
                "selected_horizontal_group_id": {"type": "integer", "minimum": 1}
            },
            "required": []
        },
        "offset": {"type": "integer", "minimum": 0},
        "limit": {"type": "integer", "minimum": 1, "description": "Page size from 1 to 200; defaults to 60."}
    },
    "required": ["report_config_ref", "choice"]
}

{
    "type": "object",
    "properties": {
        "report_config_ref": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{24}$",
            "description": "Required exact configuration returned by accounting_report_describe or accounting_report_select. It already binds the catalog report entry, selected identity, configuration, current user, and selected companies. Do not substitute null or a configuration built for different companies."
        },
        "columns": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Required nonempty list of expression labels from report_config.options.columns returned by accounting_report_describe or accounting_report_select. Each label selects all matching columns across all periods and groups. To read every column, provide every expression label."
        },
        "line_codes": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Stable static line codes returned by describing that exact identity. If nonempty, reuse that describe result's report_config_ref; identity selectors are not accepted by this tool. Omit for normal rendered-row order."
        },
        "offset": {"type": "integer", "minimum": 0},
        "limit": {"type": "integer", "minimum": 1, "description": "Page size from 1 to 200; defaults to 60."}
    },
    "required": ["report_config_ref", "columns"]
}

{
    "type": "object",
    "properties": {
        "line_ref": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{24}$",
            "description": "Required exact opaque reference returned by a dynamic or load-more row. It binds the saved report configuration, selected column labels, and current user."
        },
        "offset": {"type": "integer", "minimum": 0},
        "limit": {"type": "integer", "minimum": 1, "description": "Page size from 1 to 200; defaults to 60."}
    },
    "required": ["line_ref"]
}

{
    "type": "object",
    "properties": {
        "report_config_ref": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_-]{24}$",
            "description": "Required exact configuration returned by the get-values call supporting the answer. It already binds the catalog report entry, selected identity, configuration, current user, and selected companies; do not substitute null or add overrides."
        }
    },
    "required": ["report_config_ref"]
}

{
    "type": "object",
    "properties": {
        "audit_id": {
            "anyOf": [
                {"type": "integer", "minimum": 1},
                {"type": "null"}
            ],
            "description": "Working audit-file ID, or null to clear this session's selection."
        }
    },
    "required": ["audit_id"]
}

{
    "type": "object",
    "properties": {
        "audit_id": {
            "type": "integer",
            "minimum": 1,
            "description": "Native audit working-file ID."
        },
        "cycle": {
            "type": "string",
            "description": "Copy the native cycle code from accounting_audit_get_checks."
        },
        "offset": {
            "type": "integer",
            "minimum": 0
        },
        "limit": {
            "type": "integer",
            "minimum": 1,
            "description": "Page size from 1 to 200; defaults to 60."
        }
    },
    "required": [
        "audit_id"
    ]
}

{
    "type": "object",
    "properties": {
        "audit_id": {
            "type": "integer",
            "minimum": 1,
            "description": "Native audit working-file ID."
        },
        "cycle": {
            "type": "string",
            "description": "Copy the native cycle code from accounting_audit_get_checks."
        },
        "updates": {
            "type": "array",
            "description": "Between 1 and 100 findings for distinct non-file checks in this cycle.",
            "items": {
                "type": "object",
                "properties": {
                    "check_code": {
                        "type": "string"
                    },
                    "notes": {
                        "type": "string",
                        "description": "Plain text, without Markdown or HTML."
                    },
                    "result": {
                        "type": "string",
                        "enum": [
                            "todo",
                            "reviewed",
                            "anomaly"
                        ]
                    }
                },
                "required": [
                    "check_code",
                    "notes",
                    "result"
                ]
            }
        }
    },
    "required": [
        "audit_id",
        "cycle",
        "updates"
    ]
}
